#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<string> grid(h);
    for (int i = 0; i < h; i++) {
        cin >> grid[i];
    }

    vector<vector<char>> seen(h, vector<char>(w, 0));
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    int count = 0;
    for (int r = 0; r < h; r++) {
        for (int c = 0; c < w; c++) {
            if (grid[r][c] != '1' || seen[r][c]) continue;
            count++;
            seen[r][c] = 1;
            vector<pair<int, int>> stack = {{r, c}};
            while (!stack.empty()) {
                pair<int, int> cell = stack.back();
                stack.pop_back();
                for (int d = 0; d < 4; d++) {
                    int a = cell.first + dx[d], b = cell.second + dy[d];
                    if (a >= 0 && a < h && b >= 0 && b < w && grid[a][b] == '1' && !seen[a][b]) {
                        seen[a][b] = 1;
                        stack.push_back({a, b});
                    }
                }
            }
        }
    }
    cout << count << "\n";

    return 0;
}

